-- Eriksberg marina: seven pontoon sections across the dock basin, generated by one function.
-- Coordinates: x = -east, z = north. Each section is a platform at the east quay, a gangway
-- up to the quay, an east-west walkway reaching ~55% across the basin, and finger piers on
-- both sides (south side bow -z, north side bow +z). Budget: 63 modules, 32 berths.
local PI = math.pi
local BASIN_TILT = 0.1 -- east quay edge x = -50 + 0.1 z (z >= 0)
local HALF_W = 1.175   -- half the 2.35 m walkway
local PITCH = 6.5      -- finger spacing
local FINGER_LEN = 9
local STERN_GAP = 2.0

local hull_len = { skiff = 4.5, runabout = 5.8, cruiser = 7.6, speedboat = 8.1,
  sailboat_7m = 7.0, sailboat = 8.4 }

local palettes = {
  { { 245, 245, 240 }, { 70, 90, 120 }, { 200, 40, 40 } },
  { { 30, 60, 120 }, { 200, 190, 160 }, { 240, 240, 235 } },
  { { 235, 235, 225 }, { 150, 150, 155 }, { 30, 70, 140 } },
  { { 180, 40, 40 }, { 220, 210, 190 }, { 40, 40, 45 } },
  { { 40, 110, 90 }, { 225, 215, 190 }, { 240, 235, 220 } },
  { { 225, 170, 50 }, { 90, 70, 55 }, { 245, 245, 240 } },
  { { 90, 95, 105 }, { 190, 195, 200 }, { 230, 90, 40 } },
  { { 250, 250, 250 }, { 40, 60, 90 }, { 200, 160, 60 } }
}
local recipes = { "runabout", "cruiser", "speedboat", "cruiser", "runabout", "skiff",
  "speedboat", "sailboat_7m", "cruiser", "runabout", "speedboat", "cruiser", "skiff",
  "sailboat", "runabout" }

local berths, modules = {}, {}
local nboat = 0

local function east_edge(z)
  if z >= 0 then return -50 + BASIN_TILT * z end
  return -50 + 0.12 * z
end

local function add_berth(id, x, z, heading)
  nboat = nboat + 1
  local recipe = recipes[(nboat * 7) % #recipes + 1]
  local pal = palettes[(nboat * 3) % #palettes + 1]
  berths[#berths + 1] = { id = id, recipe = recipe, x = x, z = z, heading = heading,
    mooring = "pontoon",
    appearance = { hull = pal[1], deck = pal[2], trim = pal[3] } }
  return hull_len[recipe]
end

-- One section: origin z of the walkway centre line, flags for the north side.
-- spec = { south = {fingers, open_end}, north = {fingers, open_end} or nil }
local function section(name, zc, spec)
  local xe = east_edge(zc)
  local anchor_x = xe - 2.5
  local plat_x = anchor_x + 4 + 1.5 -- 4 m gangway, 3 m platform
  local walk_len = 28
  local walk_x = plat_x + 1.5 + walk_len / 2 -- east end abuts the platform's west edge
  local xa = plat_x + 1.5                      -- walkway east end
  modules[#modules + 1] = { id = name .. "_head", kind = "platform", x = plat_x, z = zc,
    heading = PI, length = 3, width = 3, deck_height = .74 }
  modules[#modules + 1] = { id = name .. "_walk", kind = "walkway", x = walk_x, z = zc,
    heading = PI / 2, length = walk_len, width = 2.35, deck_height = .74,
    attaches = name .. "_head" }
  modules[#modules + 1] = { id = name .. "_ramp", kind = "gangway", length = 4, width = 1.5,
    deck_height = .74, anchor = { x = anchor_x, z = zc }, attaches = name .. "_head" }
  for _, side in ipairs({ "south", "north" }) do
    local s = spec[side]
    if s then
      local sign = side == "north" and 1 or -1
      local heading = side == "north" and PI or 0
      local nf = s[1]
      for k = 0, nf - 1 do
        local fx = xa + 1.5 + k * PITCH
        modules[#modules + 1] = { id = string.format("%s_%s_f%d", name, side:sub(1, 1), k),
          kind = "finger_pier", x = fx, z = zc + sign * (HALF_W + FINGER_LEN / 2),
          heading = 0, length = FINGER_LEN, width = .6, deck_height = .74,
          attaches = name .. "_walk" }
      end
      local slots = nf - 1 + (s[2] and 1 or 0)
      for k = 0, slots - 1 do
        local bx = xa + 1.5 + (k + 0.5) * PITCH
        local len = hull_len[recipes[((nboat + 1) * 7) % #recipes + 1]]
        local bz = zc + sign * (HALF_W + STERN_GAP + len / 2)
        add_berth(string.format("%s_%s%d", name, side:sub(1, 1), k), bx, bz, heading)
      end
    end
  end
end

-- sections north to south: three inside the footbridge (z~125), four outside it.
-- Bridge z and crane z (~3) located by frames; see the report.
section("s1", 236, { south = { 4, false }, north = { 3, false } })
section("s2", 199, { south = { 3, true }, north = { 3, false } })
section("s3", 161, { south = { 3, false }, north = { 3, false } })
section("s4", 94, { south = { 3, false }, north = { 3, true } })
section("s5", 48, { south = { 3, false }, north = { 4, false } })
section("s6", -6, { south = { 3, false }, north = { 3, true } })
section("s7", -62, { north = { 4, false } })

-- Two vacant slips (s6_s0, s6_s1) free the berth budget for the two resident berths below.
do
  local kept = {}
  for _, b in ipairs(berths) do
    if b.id ~= "s6_s0" and b.id ~= "s6_s1" then kept[#kept + 1] = b end
  end
  berths = kept
end

-- Residents (M4). A path starts and ends at its berth pose with the same tangent, and a slip
-- cannot be entered backwards, so each resident lies alongside a walkway whose side is clear
-- of fingers (s7 south, and s6 south which is cleared above), bow east (heading -pi/2, x = -east).
-- Route: four tangent pieces (arc, line, arc, arc) that depart east, turn south (increasing
-- heading), loop back and arrive from the west along the walkway.
local function route(id, recipe, pcs, len, speed)
  for i, p in ipairs(pcs) do
    p.ticks = math.floor(len[i] / speed * 120 + 0.5)
    p.dwell, p.max_speed, p.max_acceleration = 0, 5, 5
  end
  return { id = id, route = "open", recipe = recipe, pieces = pcs }
end

local res_a_x, res_a_z = -46, -67.4
local res_b_x, res_b_z = -31, -68.6
berths[#berths + 1] = { id = "s7_res", recipe = "runabout", x = res_a_x, z = res_a_z,
  heading = -PI / 2, mooring = "pontoon", empty = true,
  appearance = { hull = { 240, 240, 235 }, deck = { 70, 90, 120 }, trim = { 200, 40, 40 } } }
berths[#berths + 1] = { id = "s6_res", recipe = "cruiser", x = res_b_x, z = res_b_z,
  heading = -PI / 2, mooring = "pontoon", empty = true,
  appearance = { hull = { 30, 60, 120 }, deck = { 200, 190, 160 }, trim = { 240, 240, 235 } } }

return {
  version = 3,
  marina = {
    entrance = { x = 17, z = 128, width = 8 },
    berths = berths,
    modules = modules,
    vessels = {
      { id = "ruth", recipe = "runabout",
        appearance = { hull = { 240, 240, 235 }, deck = { 70, 90, 120 }, trim = { 200, 40, 40 },
          name = "RUTH" } },
      { id = "nore", recipe = "cruiser",
        appearance = { hull = { 30, 60, 120 }, deck = { 200, 190, 160 }, trim = { 240, 240, 235 },
          name = "NORE" } }
    },
    services = {
      { id = "ruth_home", vessel = "ruth", berth = "s7_res", kind = "resident",
        route = "run_a", start_tick = 720 },
      { id = "nore_home", vessel = "nore", berth = "s6_res", kind = "resident",
        route = "run_b", start_tick = 3000 }
    }
  },
  -- The marina_pass loop craft is removed. A present vessel list replaces all compiled
  -- traffic, so the compiled ferry, river runabout and schooner are retained explicitly.
  traffic = {
    vessels = {
      -- The compiled Älvsnabben loop, with its Stenpiren dwell extended. The two later
      -- stops keep the shared remainder of the 1,200 s timetable.
      { id = "ferry", retain = "alvsnabben",
        stops = {
          { id = "stenpiren", dwell = 35 },
          { id = "lindholmspiren" },
          { id = "eriksberg" }
        } },
      -- river_runabout removed: its compiled loop (x -31..-3, z -58..98) runs through the
      -- sections south of the bridge, and the validator does not survey retained craft.
      -- The compiled schooner keeps its Hisingsbron passage and lift dependency.
      { id = "schooner", retain = "schooner" },
      route("run_a", "runabout", {
    { kind = "arc", x = -46, z = -73.4, radius = 6, start_angle = -4.71238898038469, sweep = 1.5707963267948966 },
    { kind = "line", x0 = -52, z0 = -73.4, x1 = -52, z1 = -81.4 },
    { kind = "arc", x = -42.0, z = -81.4, radius = 10.0, start_angle = -3.141592653589793, sweep = 3.141592653589793 },
    { kind = "arc", x = -46.0, z = -81.4, radius = 14, start_angle = -6.283185307179586, sweep = 1.5707963267948966 }
  }, {9.42477796076938,8,31.41592653589793,21.991148575128552}, 1.8),
      route("run_b", "cruiser", {
    { kind = "arc", x = -31, z = -74.6, radius = 6, start_angle = -4.71238898038469, sweep = 1.5707963267948966 },
    { kind = "line", x0 = -37, z0 = -74.6, x1 = -37, z1 = -98.6 },
    { kind = "arc", x = -19.0, z = -98.6, radius = 18.0, start_angle = -3.141592653589793, sweep = 3.141592653589793 },
    { kind = "arc", x = -31.0, z = -98.6, radius = 30, start_angle = -6.283185307179586, sweep = 1.5707963267948966 }
  }, {9.42477796076938,24,56.548667764616276,47.12388980384689}, 2.2)
    }
  },
  -- One flock wheels just north of the slips, with a feeding pass early in the first
  -- minute and a short alarm climb afterwards. Cue ticks use the 120 Hz session clock.
  gulls = {
    flocks = {
      { id = "harbor", recipe = "gull", x = -4, z = 182, count = 8,
        seed = 3, phase = 0, radius = 10, height = 6, rate = 0.3,
        cues = {
          { kind = "feeding", start = 240, stop = 600, fade = 60, amplitude = 0.8 },
          { kind = "alarm", start = 900, stop = 1200, fade = 80, amplitude = 1.0 }
        } }
    }
  }
}
